pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selector, uint256 rawId) public {
        // WIDE domain: the fuzzer picks which interface to probe (contract-defined ids)
        // or an arbitrary id, keeping the IERC165 probe reachable with high probability.
        selector = bound(selector, 0, 2);
        bytes4 iid;
        if (selector == 0) {
            iid = type(IERC165).interfaceId;
        } else if (selector == 1) {
            iid = type(IAccessControl).interfaceId;
        } else {
            iid = bytes4(uint32(rawId));
        }

        // General rule: interface support is exactly {IERC165, IAccessControl} —
        // inheritance through ERC165 guarantees IERC165 is reported as supported.
        bool expected = (iid == type(IERC165).interfaceId) || (iid == type(IAccessControl).interfaceId);
        bool ok = true;
        try c.supportsInterface(iid) returns (bool supported) {
            ok = (supported == expected);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

