pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(uint256 seed) public {
        // Derive the canonical interface ids from their selector definitions
        bytes4 acId =
            bytes4(keccak256("hasRole(bytes32,address)")) ^
            bytes4(keccak256("getRoleAdmin(bytes32)")) ^
            bytes4(keccak256("grantRole(bytes32,address)")) ^
            bytes4(keccak256("revokeRole(bytes32,address)")) ^
            bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 erc165Id = bytes4(keccak256("supportsInterface(bytes4)"));

        // Map the fuzzed seed onto the admissible query space: the two
        // canonical ids plus arbitrary fuzzed ids (kept wide).
        bytes4 iid;
        uint256 branch = seed % 3;
        if (branch == 0) {
            iid = acId;
        } else if (branch == 1) {
            iid = erc165Id;
        } else {
            iid = bytes4(uint32(uint256(keccak256(abi.encode(seed)))));
        }

        // Rule: for ANY queried interface id, the contract reports support
        // exactly for the IAccessControl id and the IERC165 id (the ERC165
        // super fallback). The mutant drops the fallback, so when the IERC165
        // id is queried it returns false and breaks the biconditional.
        assertTrue(c.supportsInterface(iid) == (iid == acId || iid == erc165Id));
    }
}

